styles:
p.dummy a {
    color: #0066cc !important;
    text-decoration: underline !important;
}
/* ==================================================
   福岡 医療ダイエット3院比較表
   横スクロールなし・縦スクロールあり
================================================== */

.fukuoka-diet-compare-wrap {
    width: 100% !important;
    max-width: 100% !important;
    margin: 12px 0 !important;
    padding: 0 !important;

    font-family:
        "Yu Gothic",
        "Hiragino Kaku Gothic ProN",
        Meiryo,
        sans-serif !important;

    box-sizing: border-box !important;
}

.fukuoka-diet-compare-wrap *,
.fukuoka-diet-compare-wrap *::before,
.fukuoka-diet-compare-wrap *::after {
    box-sizing: border-box !important;
}


/* ==================================================
   縦スクロールエリア
================================================== */

.fukuoka-diet-table-scroll {
    width: 100% !important;
    max-width: 100% !important;

    max-height: 380px !important;

    overflow-x: hidden !important;
    overflow-y: auto !important;

    margin: 0 !important;
    padding: 0 !important;

    background: #fff !important;

    border: 1px solid #d7d7d7 !important;
    border-radius: 5px !important;

    -webkit-overflow-scrolling: touch;

    box-sizing: border-box !important;
}


/* ==================================================
   テーブル本体
================================================== */

table.fukuoka-diet-table {
    width: 100% !important;
    min-width: 0 !important;
    max-width: 100% !important;

    margin: 0 !important;
    padding: 0 !important;

    border-collapse: separate !important;
    border-spacing: 0 !important;

    table-layout: fixed !important;

    background: #fff !important;

    color: #333 !important;

    font-size: 11px !important;
    line-height: 1.35 !important;
}


/* ==================================================
   列幅
================================================== */

/* 比較項目 */
table.fukuoka-diet-table th:first-child,
table.fukuoka-diet-table td:first-child {
    width: 10% !important;
}


/* 3院 */
table.fukuoka-diet-table th:nth-child(2),
table.fukuoka-diet-table td:nth-child(2),
table.fukuoka-diet-table th:nth-child(3),
table.fukuoka-diet-table td:nth-child(3),
table.fukuoka-diet-table th:nth-child(4),
table.fukuoka-diet-table td:nth-child(4) {
    width: 30% !important;
}


/* ==================================================
   全セル
================================================== */

table.fukuoka-diet-table th,
table.fukuoka-diet-table td {
    margin: 0 !important;

    padding: 6px 3px !important;

    border: 0 !important;
    border-right: 1px solid #dedede !important;
    border-bottom: 1px solid #dedede !important;

    color: #333 !important;

    text-align: center !important;
    vertical-align: middle !important;

    font-size: 11px !important;
    line-height: 1.35 !important;

    white-space: normal !important;

    word-break: break-word !important;
    overflow-wrap: anywhere !important;

    box-sizing: border-box !important;
}


/* 右端線を削除 */
table.fukuoka-diet-table tr > *:last-child {
    border-right: 0 !important;
}


/* ==================================================
   固定ヘッダー
================================================== */

table.fukuoka-diet-table thead th {
    position: sticky !important;
    top: 0 !important;
    z-index: 20 !important;

    background: #f8e8ed !important;

    color: #333 !important;

    padding: 6px 3px !important;

    border-bottom: 2px solid #b75062 !important;

    font-weight: 700 !important;

    box-shadow: 0 1px 3px rgba(0,0,0,.05) !important;
}


/* 左上 */
table.fukuoka-diet-table thead th.fukuoka-diet-item-head {
    background: #9f2936 !important;
    color: #fff !important;

    font-size: 8.5px !important;
    line-height: 1.15 !important;

    padding-left: 1px !important;
    padding-right: 1px !important;
}


/* ==================================================
   キャッチコピー
================================================== */

.fukuoka-diet-target {
    display: block !important;

    margin: 0 0 3px !important;
    padding: 0 !important;

    color: #a8324b !important;

    font-size: 9.5px !important;
    font-weight: 700 !important;
    line-height: 1.15 !important;

    letter-spacing: -0.2px !important;
}


/* ==================================================
   クリニック名
================================================== */

.fukuoka-diet-clinic-name {
    display: block !important;

    margin: 0 0 4px !important;
    padding: 0 !important;

    color: #333 !important;

    font-size: 11.5px !important;
    font-weight: 700 !important;
    line-height: 1.3 !important;
}


/* ==================================================
   ボタン
================================================== */

table.fukuoka-diet-table a.fukuoka-diet-btn {
    display: inline-block !important;

    width: auto !important;
    max-width: 100% !important;

    margin: 0 auto !important;
    padding: 4px 7px !important;

    background: #c6405d !important;
    color: #fff !important;

    border: 0 !important;
    border-radius: 3px !important;

    text-decoration: none !important;

    font-size: 9px !important;
    font-weight: 700 !important;
    line-height: 1.2 !important;

    white-space: normal !important;

    box-shadow: none !important;
}

table.fukuoka-diet-table a.fukuoka-diet-btn:hover {
    background: #ae344d !important;
    color: #fff !important;
}


/* ==================================================
   左側 比較項目
================================================== */

table.fukuoka-diet-table tbody th.fukuoka-diet-item-head {
    background: #f1f1f1 !important;

    color: #333 !important;

    font-size: 8.5px !important;
    font-weight: 700 !important;

    text-align: center !important;

    padding: 5px 1px !important;

    border-right: 1px solid #ccc !important;

    line-height: 1.15 !important;

    word-break: break-all !important;
}


/* ==================================================
   料金
================================================== */

table.fukuoka-diet-table tr.fukuoka-diet-price-row th,
table.fukuoka-diet-table tr.fukuoka-diet-price-row td {
    padding-top: 5px !important;
    padding-bottom: 5px !important;
}

.fukuoka-diet-price-line {
    display: block !important;

    margin: 0 !important;
    padding: 0 !important;

    text-align: center !important;

    font-size: 10.5px !important;
    line-height: 1.2 !important;
}

.fukuoka-diet-price-line + .fukuoka-diet-price-line {
    margin-top: 4px !important;
}

.fukuoka-diet-price-line strong {
    display: inline !important;

    margin: 0 !important;
    padding: 0 !important;

    color: #333 !important;

    font-size: 10.5px !important;
    font-weight: 700 !important;
}

.fukuoka-diet-price-line span {
    display: inline !important;

    margin: 0 !important;
    padding: 0 !important;

    color: #c52e50 !important;

    font-size: 10.5px !important;
    font-weight: 700 !important;
}


/* ==================================================
   おすすめポイント
================================================== */

.fukuoka-diet-point {
    font-size: 10.5px !important;
    font-weight: 700 !important;

    line-height: 1.35 !important;
}


/* ==================================================
   背景色
================================================== */

table.fukuoka-diet-table tbody tr:nth-child(odd) td {
    background: #fff !important;
}

table.fukuoka-diet-table tbody tr:nth-child(even) td {
    background: #fafafa !important;
}

table.fukuoka-diet-table tbody tr:nth-child(odd) th.fukuoka-diet-item-head {
    background: #f2f2f2 !important;
}

table.fukuoka-diet-table tbody tr:nth-child(even) th.fukuoka-diet-item-head {
    background: #eaeaea !important;
}


/* ==================================================
   住所
================================================== */

.fukuoka-diet-address {
    font-size: 9.5px !important;
    line-height: 1.3 !important;
}


/* ==================================================
   スクロールバー
================================================== */

.fukuoka-diet-table-scroll::-webkit-scrollbar {
    width: 6px;
}

.fukuoka-diet-table-scroll::-webkit-scrollbar-track {
    background: #f3f3f3;
}

.fukuoka-diet-table-scroll::-webkit-scrollbar-thumb {
    background: #c4c4c4;
    border-radius: 10px;
}


/* ==================================================
   スマホ
================================================== */

@media screen and (max-width: 768px) {

    .fukuoka-diet-compare-wrap {
        margin: 10px 0 !important;
    }


    .fukuoka-diet-table-scroll {
        max-height: 360px !important;

        overflow-x: hidden !important;
        overflow-y: auto !important;
    }


    /* ==================================================
       列幅
    ================================================== */

    /* 比較項目をさらに細く */
    table.fukuoka-diet-table th:first-child,
    table.fukuoka-diet-table td:first-child {
        width: 9% !important;
    }


    /* 3院 */
    table.fukuoka-diet-table th:nth-child(2),
    table.fukuoka-diet-table td:nth-child(2),
    table.fukuoka-diet-table th:nth-child(3),
    table.fukuoka-diet-table td:nth-child(3),
    table.fukuoka-diet-table th:nth-child(4),
    table.fukuoka-diet-table td:nth-child(4) {
        width: 30.33% !important;
    }


    /* ==================================================
       セル
    ================================================== */

    table.fukuoka-diet-table th,
    table.fukuoka-diet-table td {
        padding: 5px 2px !important;

        font-size: 10.5px !important;
        line-height: 1.3 !important;
    }


    /* ==================================================
       固定ヘッダー
    ================================================== */

    table.fukuoka-diet-table thead th {
        padding: 5px 2px !important;
    }


    table.fukuoka-diet-table thead th.fukuoka-diet-item-head {
        padding-left: 0 !important;
        padding-right: 0 !important;

        font-size: 7.5px !important;
        line-height: 1.1 !important;
    }


    /* ==================================================
       キャッチ
    ================================================== */

    .fukuoka-diet-target {
        margin-bottom: 3px !important;

        font-size: 8.5px !important;
        line-height: 1.1 !important;

        letter-spacing: -0.3px !important;
    }


    /* ==================================================
       クリニック名
    ================================================== */

    .fukuoka-diet-clinic-name {
        margin-bottom: 3px !important;

        font-size: 10.5px !important;
        line-height: 1.25 !important;
    }


    /* ==================================================
       ボタン
    ================================================== */

    table.fukuoka-diet-table a.fukuoka-diet-btn {
        padding: 3px 5px !important;

        font-size: 8px !important;
        line-height: 1.15 !important;
    }


    /* ==================================================
       左側 比較項目
    ================================================== */

    table.fukuoka-diet-table tbody th.fukuoka-diet-item-head {
        padding: 4px 0 !important;

        font-size: 7.5px !important;
        line-height: 1.1 !important;

        word-break: break-all !important;
    }


    /* ==================================================
       料金
    ================================================== */

    .fukuoka-diet-price-line,
    .fukuoka-diet-price-line strong,
    .fukuoka-diet-price-line span {
        font-size: 9.5px !important;
        line-height: 1.15 !important;
    }


    /* ==================================================
       おすすめポイント
    ================================================== */

    .fukuoka-diet-point {
        font-size: 9.5px !important;
        line-height: 1.3 !important;
    }


    /* ==================================================
       住所
    ================================================== */

    .fukuoka-diet-address {
        font-size: 8.5px !important;
        line-height: 1.25 !important;
    }
}
